windowclass.script:
function onInit()
	self.onLockModeChanged(WindowManager.getWindowReadOnlyState(self));
	onDiceChanged();
end

function onLockModeChanged(bReadOnly)
	local tFields = { "type", 
		"scale", 
		"crew", 
		"skill", 
		"skillspecialty", 
		"weaponspecialization", 
		"maneuverability", 
		"body", 
		"altitude", 
		"cover", 
		"cargo", 
		"length", 
		"space", 
		"reach", 
		"cost", 
		"weight", 
		"speed", 
		"notes", };
	WindowManager.callSafeControlsSetLockMode(self, tFields, bReadOnly);
	divider2.setVisible(WindowManager.getAnyControlVisible(self, { "type", }));
	divider3.setVisible(WindowManager.getAnyControlVisible(self, { "notes", }));
end
function onDiceChanged()
	local bShow = not mdice.isEmpty();
	mdice.setVisible(bShow);
	mbutton_roll.setVisible(bShow);

	local bBShow = not bdice.isEmpty();
	bdice.setVisible(bBShow);
	bbutton_roll.setVisible(bBShow);
end

function action(draginfo)
	local sLabel = maneuverability_label.getValue();
	local aDice = mdice.getDice();
	local nMod = mbonus.getValue();

	if mdice.isEmpty() then
		if draginfo then
			draginfo.setType("number");
			draginfo.setDescription(sLabel);
			draginfo.setStringData(sLabel);
			draginfo.setNumberData(nMod);
		else
			ModifierStack.addSlot(sLabel, nMod);
		end
	else
		local rRoll = { sType = "dice", sDesc = maneuverability_label.getValue(), aDice = mdice.getDice(), nMod = mbonus.getValue() };
		ActionsManager.performAction(draginfo, nil, rRoll);
	end
	return true;
end
function onDrop(x, y, draginfo)
	local sDragType = draginfo.getType();
	if sDragType == "dice" then
		local aDropDice = draginfo.getDiceData();
		Debug.console("Dice Data : ",aDropDice);
		for _,vDie in ipairs(aDropDice) do
			if y > 300 then
				Debug.console("adding body");
				bdice.addDie(vDie.type);
			else
				Debug.console("adding manuv");
				mdice.addDie(vDie.type);
			end
		end
		return true;
	end
end

function baction(draginfo)
	local sLabel = body_label.getValue();
	local aDice = bdice.getDice();
	local nMod = bbonus.getValue();

	if bdice.isEmpty() then
		if draginfo then
			draginfo.setType("number");
			draginfo.setDescription(sLabel);
			draginfo.setStringData(sLabel);
			draginfo.setNumberData(nMod);
		else
			ModifierStack.addSlot(sLabel, nMod);
		end
	else
		local rRoll = { sType = "dice", sDesc = body_label.getValue(), aDice = bdice.getDice(), nMod = bbonus.getValue() };
		ActionsManager.performAction(draginfo, nil, rRoll);
	end
	return true;
end

number_listitem_right.script:
function onDragStart(button, x, y, draginfo)
	return window.action(draginfo);
end

dice_listitem_right.script:
function onValueChanged()
	window.onDiceChanged();
end
function onDragStart(button, x, y, draginfo)
	draginfo.setDescription("manuverability");
	return window.action(draginfo);
end

button_listitem_roll_right.script:
function onDragStart(button, x, y, draginfo)
	return window.action(draginfo);
end
function onButtonPress()
	return window.action();
end

number_listitem_right.script:
function onDragStart(button, x, y, draginfo)
	return window.baction(draginfo);
end

dice_listitem_right.script:
function onValueChanged()
	window.onDiceChanged();
end
function onDragStart(button, x, y, draginfo)
	draginfo.setDescription("body");
	return window.baction(draginfo);
end

button_listitem_roll_right.script:
function onDragStart(button, x, y, draginfo)
	return window.baction(draginfo);
end
function onButtonPress()
	return window.baction();
end

windowlist.script:
function onDrop(x, y, draginfo)
	local sDragType = draginfo.getType();
	if sDragType == "number" then
		local w = createWindow(nil, true);
		if w then
			w.label.setValue(draginfo.getDescription());
			w.bonus.setValue(draginfo.getNumberData());
		end
		return true;
	elseif sDragType == "dice" then
		local aDropDice = draginfo.getDiceData();
		local w = getWindowAt(x,y);
		if w then
			for _,vDie in ipairs(aDropDice) do
				Debug.console("adding die to weapon",w);
			end
		end
		return true;
	end
end
